import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from './peopleQuery';
import { PersonForm } from './PersonForm';
import { useEditingPerson } from './useEditingPerson';
import { useShowRetired } from './useShowRetired';

function People({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId));
  const [, setEditingId] = useEditingPerson();
  const [showRetired, setShowRetired] = useShowRetired();
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const listed = (people.data ?? []).filter((p) => showRetired || !p.retiredFrom);

  return (
    <section data-testid="people">
      <h3>People</h3>
      <PersonForm sheetId={sheetId} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      {people.isError && <p data-testid="people-load-error">Could not load the people.</p>}
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonHeaders.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditingId(p.id)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed name or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 10,
  Component: ({ sheetId }) => <People key={sheetId} sheetId={sheetId} />,
});
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they are on hold: while held, their OPEN claims count in no live total.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean };

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed, kept in the URL: off when the screen is first opened, and left as it is by loading a sheet. */
export function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { patronIdsOf, patronsQuery } from '../patrons/patronsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate } from '../settings/settingsQuery';
import { figure, personDue, ratesQuery, sumDue } from './ratesQuery';

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates, floor, late } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person, floor, late)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late)}</td>;
}

/** A person's backing: their patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
function PersonBacking({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const ids = patronIdsOf(useQuery(patronsQuery(sheetId)).data ?? [], personId);
  const dues = people.filter((p) => ids.includes(p.id)).map((p) => personDue(p, people, claims, rates, today, floor, late));
  return <td data-testid="person-backing">{sumDue(dues)}</td>;
}

function DueTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{sumDue(people.map((p) => personDue(p, people, claims, rates, today, floor, late)))}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 15, Component: PersonDueTotal }),
  PersonHeaders.fill({ order: 22, Component: () => <th>Backing</th> }),
  PersonCells.fill({ order: 22, Component: PersonBacking }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
];

